package com.johnny.hotel.workforce;
import com.johnny.hotel.HotelBackendApplication;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.support.WalletDevelopmentGuard;import com.johnny.hotel.task.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import java.math.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=HotelBackendApplication.class,properties={"hotel.wallet.dev.fixture=true","logging.level.org.springframework=WARN","logging.level.com.johnny=WARN"}) @EnabledIfSystemProperty(named="hotel.wallet.dev.tests",matches="true") @TestInstance(TestInstance.Lifecycle.PER_CLASS) @TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class WorkforceDevelopmentTest {
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){var e=WalletDevelopmentGuard.settings();r.add("spring.datasource.url",WalletDevelopmentGuard::url);r.add("spring.datasource.username",()->e.get("DB_USERNAME"));r.add("spring.datasource.password",()->e.get("DB_PASSWORD"));r.add("spring.data.redis.password",()->e.get("REDIS_PASSWORD"));}
 @Autowired JdbcTemplate jdbc;@Autowired AttendanceService attendance;@Autowired LeaveService leave;@Autowired WorkforceApprovalRouting routing;@Autowired HotelTaskService tasks;@Autowired org.flywaydb.core.Flyway flyway;
 long department,leader,employee,concurrentEmployee,hotelManager,hr,owner,owner2;long paidType,unpaidType;String run="wf_"+UUID.randomUUID().toString().replace("-","").substring(0,10);
 long user(String suffix,String role,long dept){jdbc.update("INSERT INTO sys_user(department_id,username,password,real_name,email,status) VALUES(?,?,?,?,?,1)",dept,run+suffix,"test",suffix,run+suffix+"@example.test");long id=jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?",Long.class,run+suffix);jdbc.update("INSERT INTO sys_user_role(user_id,role_id) SELECT ?,id FROM sys_role WHERE role_code=?",id,role);return id;}
 void as(long id,String role){var a=new UsernamePasswordAuthenticationToken(run,"n/a",List.of(new SimpleGrantedAuthority("ROLE_"+role)));a.setDetails(id);SecurityContextHolder.getContext().setAuthentication(a);}
 WorkforceRequests.LeaveCreate request(long type,LocalDateTime start,LocalDateTime end,String key,BigDecimal amount){var r=new WorkforceRequests.LeaveCreate();r.setLeaveTypeId(type);r.setStartAt(start);r.setEndAt(end);r.setRequestedAmount(amount);r.setReason("Workforce test");r.setRequestKey(run+key);return r;}
 @BeforeAll void seed(){assertEquals("61",flyway.info().current().getVersion().getVersion());jdbc.update("INSERT INTO department(name,status) VALUES(?,1)",run+"dept");department=jdbc.queryForObject("SELECT id FROM department WHERE name=?",Long.class,run+"dept");leader=user("leader","STAFF",department);employee=user("employee","STAFF",department);concurrentEmployee=user("parallel","STAFF",department);hotelManager=user("hotelmanager","MANAGER",department);hr=user("hr","HR_ADMIN",department);owner=user("owner","OWNER",department);jdbc.update("UPDATE department SET manager_user_id=? WHERE id=?",leader,department);
  as(hr,"HR_ADMIN");routing.configure(null);var t=new WorkforceRequests.LeaveTypeWrite();t.setCode(run+"ANNUAL");t.setName("Annual");t.setUnit("DAY");t.setPaidTreatment("PAID");t.setRequiresBalance(true);t.setActive(true);paidType=leave.writeType(null,t).getId();t.setCode(run+"UNPAID");t.setName("Unpaid");t.setUnit("HOUR");t.setPaidTreatment("UNPAID");t.setRequiresBalance(false);unpaidType=leave.writeType(null,t).getId();for(long id:List.of(employee,concurrentEmployee)){var a=new WorkforceRequests.AllocationCreate();a.setEmployeeId(id);a.setLeaveTypeId(paidType);a.setPeriodStart(LocalDate.now());a.setPeriodEnd(LocalDate.now().plusYears(1));a.setAmount(id==employee?new BigDecimal("5.00"):new BigDecimal("1.00"));a.setReason("Initial allocation");a.setRequestKey(run+"alloc"+id);leave.allocate(a);}}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test @Order(1) void attendanceFactsIdempotencyAndServerMetadata(){as(employee,"STAFF");LocalDateTime before=LocalDateTime.now().minusSeconds(1);var in=attendance.checkIn(run+"in1","2001:db8::1","JUnit");assertTrue(!in.getEffectiveCheckIn().isBefore(before));assertEquals(in.getId(),attendance.checkIn(run+"in1","2001:db8::1","JUnit").getId());assertThrows(BusinessException.class,()->attendance.checkIn(run+"in2","127.0.0.1",null));var out=attendance.checkOut(run+"out1","127.0.0.1","JUnit");assertNotNull(out.getEffectiveCheckOut());assertThrows(BusinessException.class,()->attendance.checkOut(run+"out2","127.0.0.1",null));assertEquals("2001:db8::1",jdbc.queryForObject("SELECT ip_address FROM attendance_punch WHERE request_key=?",String.class,run+"in1"));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM attendance_punch WHERE session_id=?",Integer.class,in.getId()));}
 @Test @Order(2) void concurrentDoubleCheckInOnlyOneOpenSession()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(2);AtomicInteger success=new AtomicInteger();List<Future<?>> futures=new ArrayList<>();for(int i=0;i<2;i++){int n=i;futures.add(pool.submit(()->{as(concurrentEmployee,"STAFF");try{attendance.checkIn(run+"cin"+n,"127.0.0.1",null);success.incrementAndGet();}catch(BusinessException ignored){}finally{SecurityContextHolder.clearContext();}}));}for(var f:futures)f.get(10,TimeUnit.SECONDS);pool.shutdownNow();assertEquals(1,success.get());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM attendance_session WHERE employee_id=? AND status=0",Integer.class,concurrentEmployee));as(concurrentEmployee,"STAFF");attendance.checkOut(run+"cout","127.0.0.1",null);}
 @Test @Order(3) void correctionPreservesPunchAndRoutesToDepartmentLeader(){as(employee,"STAFF");int punches=jdbc.queryForObject("SELECT COUNT(*) FROM attendance_punch WHERE employee_id=?",Integer.class,employee);var r=new WorkforceRequests.CorrectionCreate();r.setCorrectionType("MISSING_CHECK_IN");r.setRequestedCheckIn(LocalDateTime.now().minusDays(1).withHour(23));r.setRequestedCheckOut(LocalDateTime.now().withHour(7));r.setReason("Forgot punch");r.setRequestKey(run+"corr1");var c=attendance.requestCorrection(r);assertEquals(leader,c.getApproverUserIdSnapshot());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM todo WHERE task_id=? AND user_id=? AND status=0",Integer.class,c.getTaskId(),leader));as(hotelManager,"MANAGER");assertThrows(AccessDeniedException.class,()->attendance.decideCorrection(c.getId(),true,null));as(leader,"STAFF");attendance.decideCorrection(c.getId(),true,null);assertEquals(punches,jdbc.queryForObject("SELECT COUNT(*) FROM attendance_punch WHERE employee_id=?",Integer.class,employee));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM attendance_correction_fact WHERE request_id=?",Integer.class,c.getId()));assertEquals(2,jdbc.queryForObject("SELECT status FROM hotel_task WHERE id=?",Integer.class,c.getTaskId()));}
 @Test @Order(4) void leaveLifecycleBalanceAndTaskAuthority(){LocalDateTime start=LocalDateTime.now().plusDays(20).withHour(0).withMinute(0).withSecond(0).withNano(0);as(employee,"STAFF");var draft=leave.create(request(paidType,start,start.plusDays(1),"leave1",BigDecimal.ONE));var pending=leave.submit(draft.getId());assertEquals(leader,pending.getApproverUserIdSnapshot());assertEquals(0,jdbc.queryForObject("SELECT status FROM todo WHERE task_id=?",Integer.class,pending.getTaskId()));assertThrows(AccessDeniedException.class,()->tasks.get(pending.getTaskId()));assertThrows(BusinessException.class,()->tasks.complete(pending.getTaskId(),"bypass"));as(hotelManager,"MANAGER");assertThrows(AccessDeniedException.class,()->leave.decide(draft.getId(),true,null));as(hr,"HR_ADMIN");assertThrows(AccessDeniedException.class,()->leave.decide(draft.getId(),true,null));as(leader,"STAFF");assertEquals(2,leave.decide(draft.getId(),true,null).getStatus());as(employee,"STAFF");var balance=leave.balance(paidType,LocalDate.now(),LocalDate.now().plusYears(1));assertEquals(0,new BigDecimal("4.00").compareTo(balance.getAvailable()));assertEquals(0,new BigDecimal("1.00").compareTo(balance.getApproved()));}
 @Test @Order(5) void overlapCancellationAndUnbalancedHourlyLeave(){LocalDateTime start=LocalDateTime.now().plusDays(20).withHour(12).withMinute(0).withSecond(0).withNano(0);as(employee,"STAFF");var overlap=leave.create(request(unpaidType,start,start.plusHours(2),"overlap",new BigDecimal("2.00")));assertThrows(BusinessException.class,()->leave.submit(overlap.getId()));var future=leave.create(request(paidType,start.plusDays(3),start.plusDays(4),"cancel",BigDecimal.ONE));leave.submit(future.getId());assertEquals(4,leave.cancel(future.getId(),"Plans changed").getStatus());var hourly=leave.create(request(unpaidType,start.plusDays(5),start.plusDays(5).plusHours(3),"hourly",new BigDecimal("3.00")));leave.submit(hourly.getId());as(leader,"STAFF");assertEquals(3,leave.decide(hourly.getId(),false,"Coverage unavailable").getStatus());}
 @Test @Order(6) void concurrentBalanceReservationCannotOversubscribe()throws Exception{LocalDateTime start=LocalDateTime.now().plusDays(80).withHour(0).withMinute(0).withSecond(0).withNano(0);as(concurrentEmployee,"STAFF");var a=leave.create(request(paidType,start,start.plusDays(1),"pa",BigDecimal.ONE));var b=leave.create(request(paidType,start.plusDays(2),start.plusDays(3),"pb",BigDecimal.ONE));ExecutorService pool=Executors.newFixedThreadPool(2);AtomicInteger success=new AtomicInteger();var calls=List.of(pool.submit(()->submitAs(concurrentEmployee,a.getId(),success)),pool.submit(()->submitAs(concurrentEmployee,b.getId(),success)));for(var f:calls)f.get(10,TimeUnit.SECONDS);pool.shutdownNow();assertEquals(1,success.get());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM employee_leave_request WHERE employee_id=? AND status=1",Integer.class,concurrentEmployee));}
 void submitAs(long id,long request,AtomicInteger success){as(id,"STAFF");try{leave.submit(request);success.incrementAndGet();}catch(BusinessException ignored){}finally{SecurityContextHolder.clearContext();}}
 @Test @Order(7) void leaderRoutesToHrManagerPoolAndClaimerBecomesApprover(){as(leader,"STAFF");LocalDateTime start=LocalDateTime.now().plusDays(100);var r=leave.create(request(unpaidType,start,start.plusHours(1),"self",BigDecimal.ONE));r=leave.submit(r.getId());assertNull(r.getApproverUserIdSnapshot());assertEquals("HR_MANAGER_POOL",r.getApprovalRoute());as(hr,"HR_ADMIN");r=leave.claim(r.getId());assertEquals(hr,r.getApproverUserIdSnapshot());assertEquals(2,leave.decide(r.getId(),true,null).getStatus());}
 @Test @Order(8) void attendanceOnApprovedLeaveIsReportedButPunchAllowed(){as(employee,"STAFF");var active=leave.create(request(unpaidType,LocalDateTime.now().minusMinutes(10),LocalDateTime.now().plusHours(2),"active",BigDecimal.ONE));leave.submit(active.getId());as(leader,"STAFF");leave.decide(active.getId(),true,null);as(employee,"STAFF");var session=attendance.checkIn(run+"leavein","127.0.0.1",null);assertEquals("ATTENDANCE_ON_APPROVED_LEAVE",attendance.mine(null,null,1,20).getItems().stream().filter(x->x.getId().equals(session.getId())).findFirst().orElseThrow().getExceptionCode());attendance.checkOut(run+"leaveout","127.0.0.1",null);}
 @Test @Order(9) void managerRoutesToOwnerAndOwnerIsExempt(){as(hotelManager,"MANAGER");LocalDateTime start=LocalDateTime.now().plusDays(120);var r=leave.create(request(unpaidType,start,start.plusHours(1),"manager",BigDecimal.ONE));r=leave.submit(r.getId());assertEquals("OWNER_POOL",r.getApprovalRoute());assertNull(r.getApproverUserIdSnapshot());as(owner,"OWNER");r=leave.claim(r.getId());assertEquals(owner,r.getApproverUserIdSnapshot());assertEquals(2,leave.decide(r.getId(),true,null).getStatus());assertThrows(BusinessException.class,()->leave.create(request(unpaidType,start.plusDays(2),start.plusDays(2).plusHours(1),"owner",BigDecimal.ONE)));assertThrows(BusinessException.class,()->attendance.checkIn(run+"ownerin","127.0.0.1",null));}
 @Test @Order(10) void configuredHrLeaderReceivesDepartmentLeaderRequest(){jdbc.update("INSERT INTO department(name,status) VALUES(?,1)",run+"hrdept");long hrDept=jdbc.queryForObject("SELECT id FROM department WHERE name=?",Long.class,run+"hrdept"),hrLeader=user("hrleader","STAFF",hrDept);jdbc.update("UPDATE department SET manager_user_id=? WHERE id=?",hrLeader,hrDept);as(hr,"HR_ADMIN");routing.configure(hrDept);as(leader,"STAFF");LocalDateTime start=LocalDateTime.now().plusDays(130);var r=leave.submit(leave.create(request(unpaidType,start,start.plusHours(1),"hrdirect",BigDecimal.ONE)).getId());assertEquals("HR_DEPARTMENT_LEADER_DIRECT",r.getApprovalRoute());assertEquals(hrLeader,r.getApproverUserIdSnapshot());}
 @Test @Order(11) void multipleOwnersCreateOwnerPoolAndOnlyOwnerCanClaim(){owner2=user("owner2","OWNER",department);as(hotelManager,"MANAGER");LocalDateTime start=LocalDateTime.now().plusDays(140);var r=leave.submit(leave.create(request(unpaidType,start,start.plusHours(1),"ownerpool",BigDecimal.ONE)).getId());assertEquals("OWNER_POOL",r.getApprovalRoute());assertNull(r.getApproverUserIdSnapshot());long poolRequest=r.getId();as(hr,"HR_ADMIN");assertThrows(AccessDeniedException.class,()->leave.claim(poolRequest));as(owner2,"OWNER");r=leave.claim(poolRequest);assertEquals(owner2,r.getApproverUserIdSnapshot());}
 @Test @Order(12) void correctionUsesSamePoolAndConcurrentClaimResolvesOneApprover()throws Exception{jdbc.update("UPDATE sys_user SET department_id=NULL WHERE id=?",hotelManager);as(hotelManager,"MANAGER");var input=new WorkforceRequests.CorrectionCreate();input.setCorrectionType("MISSING_CHECK_IN");input.setRequestedCheckIn(LocalDateTime.now().minusDays(2));input.setRequestedCheckOut(LocalDateTime.now().minusDays(2).plusHours(8));input.setReason("Manager correction");input.setRequestKey(run+"managercorr");var c=attendance.requestCorrection(input);assertEquals("OWNER_POOL",c.getApprovalRoute());assertNull(c.getApproverUserIdSnapshot());ExecutorService pool=Executors.newFixedThreadPool(2);AtomicInteger success=new AtomicInteger();long correctionId=c.getId();var jobs=List.of(pool.submit(()->claimCorrectionAs(owner,correctionId,success)),pool.submit(()->claimCorrectionAs(owner2,correctionId,success)));for(var job:jobs)job.get(10,TimeUnit.SECONDS);pool.shutdownNow();assertEquals(1,success.get());var resolved=jdbc.queryForObject("SELECT approver_user_id_snapshot FROM attendance_correction_request WHERE id=?",Long.class,correctionId);assertTrue(Set.of(owner,owner2).contains(resolved));}
 void claimCorrectionAs(long actor,long request,AtomicInteger success){as(actor,"OWNER");try{attendance.claimCorrection(request);success.incrementAndGet();}catch(RuntimeException ignored){}finally{SecurityContextHolder.clearContext();}}
}
